def rotate_right(nums: list[int], k: int) -> list[int]:
    if k < 0:
        raise ValueError("k must be non-negative")
    if len(nums) == 0:
        return []

    result = []
    nums_length = len(nums)
    nums_length_minus_k = nums_length - k

    # handle k > nums_length
    if nums_length_minus_k < 0:
        nums_length_minus_k = nums_length

    for i in range(nums_length_minus_k):
        result.append(nums[i])

    result.extend(nums[:k])
    result.extend(nums[nums_length - k:])

    return result

def rotate_right(nums: list[int], k: int) -> list[int]:
