def coin_change_ways(coins: list[int], amount: int) -> int:
    n = len(coins)
    if amount == 0:
        return 1

    # Base case: no coins available
    if n == 0:
        return 0

    # Create a table to store combinations
    table = [[0] * (amount + 1) for _ in range(n + 1)]

    # Fill the table recursively
    for i in range(1, n + 1):
        for j in range(1, amount + 1):
            if coins[i - 1] <= j:
                table[i][j] = table[i - 1][j] + table[i][j - coins[i - 1]]
            else:
                table[i][j] = table[i - 1][j]

    return table[n][amount]

from itertools import combinations

def coin_change_ways(coins: list[int], amount: int) -> int:
    if amount == 0:
        return 1

    combinations_result = 0
    for coin_combinations in combinations(coins, amount):
        coin_values = sum(coin for coin in coin_combinations)
        if coin_values <= amount:
            combinations_result += coin_values // amount * coin_change_ways(coin_combinations, amount - coin_values % amount)

    return combinations_result

