def lru_simulate(capacity: int, ops: list[list[str]]) -> list[int]:
    cache = defaultdict(list)

    for op in ops:
        if len(op) != 2:
            raise ValueError("Expected 2 arguments for op: put or get")

        action, key = op

        if action == 'put':
            if len(cache) >= capacity:
                del cache[key]
            cache[key].append((key, len(cache) if len(cache) < capacity else len(cache.values())[-1] + 1))
        elif action == 'get':
            if key not in cache:
                return -1

            return cache[key][-1]

    return [-1]

from collections import defaultdict

def lru_simulate(capacity: int, ops: list[list]):
    cache = defaultdict(list)

    for op in ops:
        key, *args = op
        if len(args) > 2:
            raise ValueError("Invalid operation: {}".format(op))

        if len(args) == 2:
            key, value = args
            if key in cache:
                cache[key].remove(value)
                cache[key].append(value)
            else:
                cache[key] = [value]
        elif len(args) == 1:
            key = args[0]
            if key in cache:
                return cache.pop(key)
            else:
                return -1

    results = []
    for key, values in cache.items():
        if len(values) > capacity:
            cache.popitem(last=False)
        results.append(cache[key])

    return results
